{
  "description": "The creature is shown in right-facing lateral view standing on a flat light surface. It has a low, stout, quadrupedal body with a broad flat head at the front and a thick tapering tail at the rear. The dorsal surface from the back of the neck to the base of the tail is covered in overlapping large brown keratinous scales, while the ventral surface, sides of the head, limbs, and tail are pale pink with wrinkled, fleshy skin. The head is wide and blunt-snouted with small golden eyes, small nostrils, and a wide mouth, and bears prominent pink feathery external gills on both sides of the neck. The four limbs are thick and splayed slightly outward, each ending in a five-toed foot with small claws.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, flattened and blunt-snouted with a mottled brown and pink skin, small golden eyes with dark pupils on the sides, small round nostrils at the tip of the snout, and a wide slightly upturned mouth",
      "where": "at the anterior end of the body, facing to the right"
    },
    {
      "part": "gills",
      "looks_like": "six pink fleshy stalks with fine feathery filaments, three branching stalks on each side of the head/neck, darker pink at the base and lighter at the fringed edges",
      "where": "projecting outward from the sides of the head and neck, behind the eyes"
    },
    {
      "part": "scales",
      "looks_like": "large overlapping keratinous scales in shades of dark and light brown with a slightly ridged texture, arranged in diagonal rows",
      "where": "covering the entire dorsal surface from the neck over the back and sides down to the upper limbs and base of the tail"
    },
    {
      "part": "legs",
      "looks_like": "thick, muscular, pale pink limbs with deeply wrinkled and folded skin",
      "where": "four limbs positioned under the body, two forelegs under the chest and two hindlegs under the mid-body"
    },
    {
      "part": "feet",
      "looks_like": "broad fleshy paws with five slender toes on each foot, each toe tipped with a small pale claw",
      "where": "at the distal end of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "thick, fleshy, pale pink tapering structure with wrinkled skin and a slightly flattened underside",
      "where": "extending posteriorly from the body to the left, partially visible behind the scaled back and hindlegs"
    },
    {
      "part": "markings",
      "looks_like": "irregular dark brown mottled spots on the top of the head and snout, and transverse wrinkled folds on the pale ventral skin and limbs",
      "where": "on the dorsal surface of the head and on the ventral body and limbs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "axolotl",
    "pangolin"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
